{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Roquinimex, which shares the 4-hydroxy-2-oxo heteroaromatic enol core with the query, showed complete oral bioavailability in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ketoprofen, a lipophilic weak-acid drug with an aromatic ketone, had an absolute oral bioavailability of 92% in humans, supporting high F for the similarly lipophilic weak-acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Diflunisal, a lipophilic salicylate weak acid, had an absolute oral bioavailability of 89.5%, supporting efficient absorption for the query's lipophilic weak-acid character.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a 4-hydroxycoumarin anticoagulant with essentially complete oral absorption in humans. Supportive analogues sharing lipophilic weak-acid or 4-hydroxy-heteroaromatic features (roquinimex, ketoprofen, diflunisal) all show high oral bioavailability, and the low-F records (baicalein, cromolyn, alendronate) are structurally distant and not transferable. Thus F >=20% is strongly supported.",
  "evidence_gaps": [
    "No direct warfarin absolute bioavailability record was retrieved; all retrieved analogues have Morgan similarity <0.3.",
    "No human F data for the exact query enantiomer were present in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

